CREATE TABLE public.location_to_terms(task_order_id uuid PRIMARY KEY REFERENCES public.location_task_orders(id),housing_enabled boolean NOT NULL DEFAULT false,housing_rate numeric NOT NULL DEFAULT 0,per_diem_enabled boolean NOT NULL DEFAULT false,per_diem_rate numeric NOT NULL DEFAULT 0,mobe_approved boolean NOT NULL DEFAULT false,mobe_terms text,mobe_cap numeric,line_rates jsonb NOT NULL DEFAULT '[]',updated_at timestamptz NOT NULL DEFAULT now(),CHECK(housing_rate>=0 AND per_diem_rate>=0 AND (mobe_cap IS NULL OR mobe_cap>=0)));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.location_to_terms TO authenticated;GRANT ALL ON public.location_to_terms TO service_role;ALTER TABLE public.location_to_terms ENABLE ROW LEVEL SECURITY;CREATE POLICY managers ON public.location_to_terms FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'));
CREATE TABLE public.location_to_sheets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_order_id uuid NOT NULL REFERENCES public.location_task_orders(id),kind text NOT NULL CHECK(kind IN('mobe','demobe')),required_counts jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(task_order_id,kind));
GRANT SELECT,INSERT,UPDATE,DELETE ON public.location_to_sheets TO authenticated;GRANT ALL ON public.location_to_sheets TO service_role;ALTER TABLE public.location_to_sheets ENABLE ROW LEVEL SECURITY;CREATE POLICY managers ON public.location_to_sheets FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'));
CREATE TABLE public.location_to_allocations(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),task_order_id uuid NOT NULL REFERENCES public.location_task_orders(id),line_kind text NOT NULL CHECK(line_kind IN('position','asset')),label text NOT NULL,personnel_id uuid,asset_assignment_id uuid REFERENCES public.asset_assignments(id),effective_from timestamptz NOT NULL,effective_until timestamptz,created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),CHECK((personnel_id IS NOT NULL)::int+(asset_assignment_id IS NOT NULL)::int=1));
GRANT SELECT,INSERT,UPDATE ON public.location_to_allocations TO authenticated;GRANT ALL ON public.location_to_allocations TO service_role;ALTER TABLE public.location_to_allocations ENABLE ROW LEVEL SECURITY;CREATE POLICY managers ON public.location_to_allocations FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'));CREATE INDEX to_allocations_person ON public.location_to_allocations(personnel_id,effective_from,effective_until);
CREATE TABLE public.location_to_sheet_entries(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),sheet_id uuid NOT NULL REFERENCES public.location_to_sheets(id),personnel_id uuid NOT NULL,role_label text NOT NULL,in_at timestamptz NOT NULL,out_at timestamptz NOT NULL,signature_url text NOT NULL,signed_at timestamptz NOT NULL DEFAULT now(),created_by uuid,visit_personnel_id uuid REFERENCES public.visit_personnel(id),voided_at timestamptz,CHECK(out_at>in_at),UNIQUE(sheet_id,personnel_id));
GRANT SELECT,INSERT ON public.location_to_sheet_entries TO authenticated;GRANT ALL ON public.location_to_sheet_entries TO service_role;ALTER TABLE public.location_to_sheet_entries ENABLE ROW LEVEL SECURITY;CREATE POLICY managers ON public.location_to_sheet_entries FOR ALL TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager')) WITH CHECK(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'));
CREATE TABLE public.personnel_agency_provenance(personnel_id uuid PRIMARY KEY,vendor_id uuid NOT NULL REFERENCES public.vendors(id),join_token_id uuid REFERENCES public.project_join_tokens(id),join_request_id uuid REFERENCES public.project_join_requests(id),recorded_at timestamptz NOT NULL DEFAULT now());GRANT SELECT ON public.personnel_agency_provenance TO authenticated;GRANT ALL ON public.personnel_agency_provenance TO service_role;ALTER TABLE public.personnel_agency_provenance ENABLE ROW LEVEL SECURITY;CREATE POLICY managers ON public.personnel_agency_provenance FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin') OR public.has_role(auth.uid(),'manager'));
CREATE FUNCTION public.location_to_at(p_location uuid,p_at timestamptz) RETURNS TABLE(line_kind text,label text,authorized integer) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT l.line_kind,l.label,GREATEST(0,sum(l.qty_delta))::int FROM location_task_order_lines l JOIN location_task_orders t ON t.id=l.task_order_id JOIN project_locations pl ON pl.id=t.location_id WHERE t.location_id=p_location AND t.status='accepted' AND (t.effective_date+COALESCE(t.effective_time,'00:00'::time)) AT TIME ZONE COALESCE(pl.timezone,'America/Chicago')<=p_at GROUP BY l.line_kind,l.label $$;REVOKE ALL ON FUNCTION public.location_to_at(uuid,timestamptz) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.location_to_at(uuid,timestamptz) TO authenticated,service_role;
CREATE FUNCTION public.save_location_to_engine(p_id uuid,p_location uuid,p_expected timestamptz,p_values jsonb,p_lines jsonb,p_terms jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE old location_task_orders;item jsonb;counts jsonb;result_id uuid:=COALESCE(p_id,gen_random_uuid());current_count int;delta int;k text;v text;accepted boolean;
BEGIN
IF auth.uid() IS NULL OR NOT(has_role(auth.uid(),'admin') OR has_role(auth.uid(),'manager')) THEN RAISE EXCEPTION 'Manager access required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended(p_location::text,1));IF NOT EXISTS(SELECT 1 FROM project_locations WHERE id=p_location AND status<>'closed') THEN RAISE EXCEPTION 'Location is closed or unavailable';END IF;
IF p_id IS NOT NULL THEN SELECT * INTO old FROM location_task_orders WHERE id=p_id AND location_id=p_location FOR UPDATE;IF NOT FOUND OR old.edited_at IS DISTINCT FROM p_expected THEN RAISE EXCEPTION 'Order changed; refresh before saving';END IF;IF EXISTS(SELECT 1 FROM location_to_allocations WHERE task_order_id=p_id) OR EXISTS(SELECT 1 FROM location_to_sheet_entries e JOIN location_to_sheets s ON s.id=e.sheet_id WHERE s.task_order_id=p_id) THEN RAISE EXCEPTION 'Used authorization is immutable; create a change TO';END IF;END IF;
IF p_values->>'status' NOT IN('draft','accepted') OR p_values->>'kind' NOT IN('initial','increase','decrease','demobilization') THEN RAISE EXCEPTION 'Invalid task order';END IF;accepted:=p_values->>'status'='accepted';IF p_values->>'kind'='initial' AND EXISTS(SELECT 1 FROM location_task_orders WHERE location_id=p_location AND status='accepted' AND kind='initial' AND id<>result_id) THEN RAISE EXCEPTION 'Initial order already exists; use a change';END IF;IF jsonb_typeof(p_lines)<>'array' OR jsonb_typeof(p_terms->'line_rates')<>'array' THEN RAISE EXCEPTION 'Structured lines required';END IF;
FOR item IN SELECT * FROM jsonb_array_elements(p_lines) LOOP k:=item->>'line_kind';v:=trim(item->>'label');delta:=(item->>'qty_delta')::int;IF k NOT IN('position','asset') OR v='' OR delta=0 THEN RAISE EXCEPTION 'Complete nonzero quantity lines';END IF;SELECT COALESCE(sum(l.qty_delta),0) INTO current_count FROM location_task_order_lines l JOIN location_task_orders t ON t.id=l.task_order_id WHERE t.location_id=p_location AND t.status='accepted' AND t.id<>result_id AND t.effective_date<=(p_values->>'effective_date')::date AND l.line_kind=k AND lower(l.label)=lower(v);IF current_count+delta<0 THEN RAISE EXCEPTION 'Deduction exceeds authorization for %',v;END IF;END LOOP;
FOR item IN SELECT * FROM jsonb_array_elements(p_terms->'line_rates') LOOP IF (item->>'rate')::numeric<0 OR item->>'line_kind' NOT IN('position','asset') OR trim(item->>'label')='' THEN RAISE EXCEPTION 'Invalid rate line';END IF;END LOOP;
IF p_id IS NULL THEN INSERT INTO location_task_orders(id,location_id,to_number,customer_ref,kind,effective_date,effective_time,travel_time,details,notes,document_id,status,created_via,created_by) VALUES(result_id,p_location,COALESCE(p_values->>'to_number',''),NULLIF(p_values->>'customer_ref',''),p_values->>'kind',(p_values->>'effective_date')::date,(p_values->>'effective_time')::time,(p_values->>'travel_time')::boolean,p_values->'details',p_values->>'notes',(p_values->>'document_id')::uuid,p_values->>'status','internal',auth.uid());ELSE UPDATE location_task_orders SET to_number=p_values->>'to_number',customer_ref=NULLIF(p_values->>'customer_ref',''),kind=p_values->>'kind',effective_date=(p_values->>'effective_date')::date,effective_time=(p_values->>'effective_time')::time,travel_time=(p_values->>'travel_time')::boolean,details=p_values->'details',notes=p_values->>'notes',document_id=(p_values->>'document_id')::uuid,status=p_values->>'status',edit_note='Structured authorization and billing terms updated' WHERE id=result_id;DELETE FROM location_task_order_lines WHERE task_order_id=result_id;END IF;
INSERT INTO location_task_order_lines(task_order_id,line_kind,label,qty_delta) SELECT result_id,x->>'line_kind',trim(x->>'label'),(x->>'qty_delta')::int FROM jsonb_array_elements(p_lines) x;
INSERT INTO location_to_terms(task_order_id,housing_enabled,housing_rate,per_diem_enabled,per_diem_rate,mobe_approved,mobe_terms,mobe_cap,line_rates) VALUES(result_id,COALESCE((p_terms->>'housing_enabled')::boolean,false),COALESCE((p_terms->>'housing_rate')::numeric,0),COALESCE((p_terms->>'per_diem_enabled')::boolean,false),COALESCE((p_terms->>'per_diem_rate')::numeric,0),COALESCE((p_terms->>'mobe_approved')::boolean,false),p_terms->>'mobe_terms',(p_terms->>'mobe_cap')::numeric,p_terms->'line_rates') ON CONFLICT(task_order_id) DO UPDATE SET housing_enabled=EXCLUDED.housing_enabled,housing_rate=EXCLUDED.housing_rate,per_diem_enabled=EXCLUDED.per_diem_enabled,per_diem_rate=EXCLUDED.per_diem_rate,mobe_approved=EXCLUDED.mobe_approved,mobe_terms=EXCLUDED.mobe_terms,mobe_cap=EXCLUDED.mobe_cap,line_rates=EXCLUDED.line_rates,updated_at=now();
IF accepted THEN FOR k IN SELECT unnest(ARRAY['mobe','demobe']) LOOP SELECT jsonb_agg(jsonb_build_object('label',label,'count',abs(qty_delta))) INTO counts FROM location_task_order_lines WHERE task_order_id=result_id AND line_kind='position' AND CASE WHEN k='mobe' THEN qty_delta>0 ELSE qty_delta<0 END;IF counts IS NOT NULL AND (k='demobe' OR COALESCE((p_terms->>'mobe_approved')::boolean,false)) THEN INSERT INTO location_to_sheets(task_order_id,kind,required_counts) VALUES(result_id,k,counts) ON CONFLICT(task_order_id,kind) DO UPDATE SET required_counts=EXCLUDED.required_counts;END IF;END LOOP;PERFORM sync_requirements_from_task_orders(p_location);END IF;INSERT INTO audit_logs(user_id,user_email,action_type,resource_type,resource_id,changes_after) VALUES(auth.uid(),'task-order-engine','to_engine_save','location_task_orders',result_id,jsonb_build_object('status',p_values->>'status','location_id',p_location));RETURN result_id;
END $$;REVOKE ALL ON FUNCTION public.save_location_to_engine(uuid,uuid,timestamptz,jsonb,jsonb,jsonb) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.save_location_to_engine(uuid,uuid,timestamptz,jsonb,jsonb,jsonb) TO authenticated;